SINA_SMART["physio1-lung-volumes"] = {"lecture":"physio1-lung-volumes","title":"Lung volumes and capacities","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-lung-volumes:e0","text":"Ventilation by changing thoracic volume; pressure gradients drive air.","topic":"Mechanics of breathing","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e1","text":"Inspiration: alveolar pressure < atmospheric; expiration: >.","topic":"Mechanics of breathing","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e2","text":"Volumes: VT (~500 mL), IRV, ERV, RV.","topic":"Volumes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e3","text":"RV cannot be measured by simple spirometry.","topic":"Volumes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e4","text":"VC = IRV + VT + ERV.","topic":"Capacities","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e5","text":"TLC = VC + RV; IC = IRV + VT; FRC = ERV + RV.","topic":"Capacities","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e6","text":"Minute volume = VT × RR (~6-7.5 L/min).","topic":"Capacities","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e7","text":"Obstruction (COPD, asthma) → air trapping: ↑ RV, ↑ FRC, hyperinflation.","topic":"Obstructive disease and air trapping","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-lung-volumes:e8","text":"COPD = chronic bronchitis + emphysema; ~80% due to smoking.","topic":"Obstructive disease and air trapping","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"19phcon":"a","14x73sw":"a","1tpm1e3":"a","73cub6":"a","zibm4m":"a","p5q260":"a","1d44f0u":"a","d7z7t8":"a","8rw3qu":"a","sib43l":"a","17d3pl2":"a","1o4ku5o":"a","a4vqky":"a","13qmlpr":"a","1t2g3ee":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-lung-volumes:e0":{"s":0,"u":["Ventilation by changing thoracic volume; pressure gradients drive air.","Breathing, or pulmonary ventilation , has two phases: inspiration and expiration , achieved by changing thoracic and lung volume.","In inspiration , the diaphragm and inspiratory muscles enlarge the thorax, intrapleural pressure falls (about 754), alveolar pressure drops below atmospheric (about 757) and air flows in."],"dp":[]},"physio1-lung-volumes:e1":{"s":0,"u":["Inspiration: alveolar pressure < atmospheric; expiration: >.","In expiration , the thorax recoils, alveolar pressure rises above atmospheric (about 763) and air flows out.","In inspiration , the diaphragm and inspiratory muscles enlarge the thorax, intrapleural pressure falls (about 754), alveolar pressure drops below atmospheric (about 757) and air flows in."],"dp":[]},"physio1-lung-volumes:e2":{"s":1,"u":["Volumes: VT (~500 mL), IRV, ERV, RV.","Four volumes: tidal volume (VT) , air moved in quiet breathing (about 500 mL); inspiratory reserve volume (IRV) , extra air that can be forced in after a tidal inspiration; expiratory reserve volume (ERV) , extra air that can be forced out after a tidal expiration; residual volume (RV) , air left after a maximal expiration, which spirometry alone cannot measure."],"dp":[]},"physio1-lung-volumes:e3":{"s":1,"u":["RV cannot be measured by simple spirometry."],"dp":[]},"physio1-lung-volumes:e4":{"s":2,"u":["VC = IRV + VT + ERV.","Vital capacity (VC) = IRV + VT + ERV: the maximal volume exhaled after a maximal inhalation.","Inspiratory capacity (IC) = IRV + VT: what can be inspired after a normal expiration."],"dp":[]},"physio1-lung-volumes:e5":{"s":2,"u":["TLC = VC + RV; IC = IRV + VT; FRC = ERV + RV.","Functional residual capacity (FRC) = ERV + RV: gas left after a normal expiration.","Total lung capacity (TLC) = VC + RV: all the gas after a maximal inspiration (about 6 L)."],"dp":[]},"physio1-lung-volumes:e6":{"s":2,"u":["Minute volume = VT × RR (~6-7.5 L/min).","Minute volume = VT × breaths per minute (about 6-7.5 L/min).","Recall the lecture's example: VT 500 mL = VD 150 + VA 350 mL; at 15/min VE = 7.5 L/min and VA = 5.25 L/min, while pulmonary blood flow equals cardiac output (≈ 4.9 L/min), so VA/Q ≈ 1."],"dp":[]},"physio1-lung-volumes:e7":{"s":3,"u":["Obstruction (COPD, asthma) → air trapping: ↑ RV, ↑ FRC, hyperinflation.","In obstructive lung disease (COPD, asthma) narrowed airways close early in expiration, so air is trapped : RV and FRC rise and the lung becomes hyperinflated (distended), while VC may fall."],"dp":[{"h":"Why the diaphragm flattens in COPD","t":"Air trapping keeps the lungs over-inflated, pushing the diaphragm down and flat. A flat diaphragm works at a mechanical disadvantage: it is already shortened, so it generates less force, and when it contracts it may even pull the lower ribs inward. Patients recruit neck and shoulder muscles and lean forward on their arms to help. On a chest X-ray, hyperinflated lungs, a flat diaphragm and a long thin heart are the classic signs, direct consequences of the raised RV and FRC in this lecture. Source: the lecture's air trapping and hyperinflation slides."}]},"physio1-lung-volumes:e8":{"s":3,"u":["COPD = chronic bronchitis + emphysema; ~80% due to smoking.","COPD combines chronic bronchitis and emphysema; about 80% of cases are due to smoking ; it affects 5-10% of people over 45 in the lecture's figures, and in 2015 it caused about 3.2 million deaths worldwide."],"dp":[]}},"meta":{"19phcon":{"a":"recall","vg":"physio1-lung-volumes:e2/recall/1"},"14x73sw":{"a":"recall","vg":"physio1-lung-volumes:e2/recall/2"},"1tpm1e3":{"a":"recall","vg":"physio1-lung-volumes:e4/recall/1"},"73cub6":{"a":"recall","vg":"physio1-lung-volumes:e5/recall/1"},"zibm4m":{"a":"recall","vg":"physio1-lung-volumes:e5/recall/1"},"p5q260":{"a":"recall","vg":"physio1-lung-volumes:e4/recall/1"},"1d44f0u":{"a":"recall","vg":"physio1-lung-volumes:e3/recall/1"},"d7z7t8":{"a":"recall","vg":"physio1-lung-volumes:e1/recall/1"},"8rw3qu":{"a":"recall","vg":"physio1-lung-volumes:e1/recall/1"},"sib43l":{"a":"recall","vg":"physio1-lung-volumes:e7/recall/1"},"17d3pl2":{"a":"relationship","vg":"physio1-lung-volumes:e7/relationship/1"},"1o4ku5o":{"a":"recall","vg":"physio1-lung-volumes:e8/recall/1"},"a4vqky":{"a":"relationship","vg":"physio1-lung-volumes:e8/relationship/1"},"13qmlpr":{"a":"recall","vg":"physio1-lung-volumes:e6/recall/1"},"1t2g3ee":{"a":"application","vg":"physio1-lung-volumes:e4/application/1"}},"explRev":"2f0b7ea93816"};
